import"./chunk-VC46IEJQ.js";var e=(t,o)=>({en:t,zh:o}),a=(t,o,n,r,h,i,d,l,s)=>({name:e(...t),desc:e(...o),tour:e(...n),...s?{spoiler:e(...s)}:{},source:{confidence:r,refs:h,book:e(...i),unknown:e(...d),interpretation:e(...l)}}),m={id:"vaes-dothrak",intro:{en:"The only city of the Dothraki: no walls, a broad grassy godsway, and halls built for khalasars that are mostly away. Within it no blade may be carried and no free man's blood may be shed.",zh:"\u591A\u65AF\u62C9\u514B\u4EBA\u552F\u4E00\u7684\u57CE\u5E02\uFF1A\u6CA1\u6709\u57CE\u5899\uFF0C\u53EA\u6709\u4E00\u6761\u5BBD\u9614\u7684\u8349\u5F84\u795E\u8DEF\uFF0C\u4EE5\u53CA\u4E3A\u5E38\u5E74\u5728\u5916\u7684\u5361\u62C9\u8428\u9884\u5907\u7684\u6BBF\u5B87\u3002\u57CE\u5185\u4E0D\u5F97\u643A\u5E26\u5200\u5203\uFF0C\u4E5F\u4E0D\u5F97\u8BA9\u81EA\u7531\u4EBA\u6D41\u8840\u3002"},notes:{en:"From the books: the Horse Gate of two bronze stallions, the godsway lined with plundered monuments, the Western and Eastern Markets, the Womb of the World, the Mother of Mountains, the dosh khaleen, khals' halls standing empty much of the year, and the ban on blades and bloodshed. Invented here: every position and distance, the buildings' forms, the terrain and the scale. The geography is simplified.",zh:"\u4E66\u4E2D\u53EF\u636E\uFF1A\u4E24\u5339\u9752\u94DC\u9A8F\u9A6C\u6784\u6210\u7684\u9A6C\u95E8\u3001\u9648\u5217\u63A0\u6765\u53E4\u7269\u7684\u795E\u8DEF\u3001\u897F\u5E02\u4E0E\u4E1C\u5E02\u3001\u4E16\u754C\u4E4B\u5B50\u5BAB\u3001\u7FA4\u5C71\u4E4B\u6BCD\u3001\u591A\u65AF\u5361\u6797\u3001\u4E00\u5E74\u4E2D\u5927\u534A\u7A7A\u7F6E\u7684\u53EF\u6C57\u6BBF\u5B87\uFF0C\u4EE5\u53CA\u7981\u5203\u3001\u7981\u6B62\u6D41\u8840\u7684\u6212\u5F8B\u3002\u672C\u573A\u666F\u81EA\u62DF\uFF1A\u6240\u6709\u4F4D\u7F6E\u4E0E\u8DDD\u79BB\u3001\u5EFA\u7B51\u5F62\u5236\u3001\u5730\u5F62\u548C\u6BD4\u4F8B\u3002\u5730\u7406\u5173\u7CFB\u5DF2\u4F5C\u7B80\u5316\u3002"},tour:["horse-gate","godsway-monuments","western-market","khals-halls","eastern-market","womb-of-the-world","dosh-khaleen-huts","mother-of-mountains"],sources:[{ref:"agot",checked:"memory",note:e("Daenerys's chapters in Vaes Dothrak (A Game of Thrones) are the main source; recalled, not re-read.","\u4E3B\u8981\u4F9D\u636E\u300A\u6743\u529B\u7684\u6E38\u620F\u300B\u4E2D\u4E39\u59AE\u8389\u4E1D\u5728\u7EF4\u65AF\xB7\u591A\u65AF\u62C9\u514B\u7684\u7AE0\u8282\uFF1B\u51ED\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u539F\u6587\u3002")},{ref:"awoiaf",checked:"search-snippet",note:e("Search summaries of the wiki and the Westeros.org concordance: the Horse Gate (bronze stallions whose hooves meet about a hundred feet up in a pointed arch), the plundered godsway, the walled Western Market, eastern caravans at the Eastern Market, the ban on blades, tribute of salt, silver and seed to the dosh khaleen, and the rule that only men may set foot on the Mother of Mountains. Pages could not be fetched.","\u7ECF\u7EF4\u57FA\u4E0E Westeros.org \u8BCD\u6761\u7D22\u5F15\u7684\u641C\u7D22\u6458\u8981\u5370\u8BC1\uFF1A\u9A6C\u95E8\uFF08\u4E24\u5339\u9752\u94DC\u9A8F\u9A6C\u7684\u524D\u8E44\u5728\u7EA6\u767E\u5C3A\u9AD8\u5904\u76F8\u63A5\uFF0C\u5F62\u6210\u5C16\u62F1\uFF09\u3001\u9648\u5217\u63A0\u6765\u53E4\u7269\u7684\u795E\u8DEF\u3001\u6709\u56F4\u5899\u7684\u897F\u5E02\u3001\u4E1C\u5E02\u7684\u4E1C\u65B9\u5546\u961F\u3001\u7981\u5203\u4EE4\u3001\u5411\u591A\u65AF\u5361\u6797\u732E\u4E0A\u76D0\u3001\u94F6\u4E0E\u79CD\u5B50\uFF0C\u4EE5\u53CA\u7FA4\u5C71\u4E4B\u6BCD\u53EA\u8BB8\u7537\u5B50\u8E0F\u8DB3\u3002\u9875\u9762\u672C\u8EAB\u65E0\u6CD5\u6253\u5F00\u3002")},{ref:"twoiaf",checked:"not-accessed",note:e("Companion background on Dothraki customs was not consulted.","\u672A\u67E5\u9605\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\uFF1A\u4E16\u754C\u300B\u4E2D\u5173\u4E8E\u591A\u65AF\u62C9\u514B\u4E60\u4FD7\u7684\u80CC\u666F\u8D44\u6599\u3002")}],landmarks:{"horse-gate":a(["Horse Gate","\u9A6C\u95E8"],["Two colossal bronze stallions rear on either side of the godsway; their hooves meet high overhead in a pointed arch.","\u4E24\u5339\u5DE8\u5927\u7684\u9752\u94DC\u9A8F\u9A6C\u5728\u795E\u8DEF\u4E24\u4FA7\u4EBA\u7ACB\u800C\u8D77\uFF0C\u524D\u8E44\u5728\u9AD8\u7A7A\u76F8\u63A5\uFF0C\u5F62\u6210\u4E00\u9053\u5C16\u62F1\u3002"],["Riders enter the sacred city beneath the raised hooves of two bronze stallions.","\u9A91\u624B\u4ECE\u4E24\u5339\u9752\u94DC\u9A8F\u9A6C\u9AD8\u4E3E\u7684\u524D\u8E44\u4E0B\u8FDB\u5165\u5723\u57CE\u3002"],"high",["agot","awoiaf"],["A gate of two enormous rearing bronze stallions whose hooves meet about a hundred feet above the road, at the start of the godsway.","\u795E\u8DEF\u8D77\u70B9\u5904\uFF0C\u4E24\u5339\u4EBA\u7ACB\u7684\u5DE8\u5927\u9752\u94DC\u9A8F\u9A6C\u6784\u6210\u57CE\u95E8\uFF0C\u524D\u8E44\u5728\u8DEF\u9762\u4E0A\u65B9\u7EA6\u767E\u5C3A\u5904\u76F8\u63A5\u3002"],["The statues' exact proportions, base and appearance up close.","\u96D5\u50CF\u7684\u786E\u5207\u6BD4\u4F8B\u3001\u5E95\u5EA7\u53CA\u8FD1\u770B\u7684\u6837\u8C8C\u3002"],["Anatomy and detailing are invented; the height is kept close to the stated figure.","\u9A6C\u7684\u5F62\u4F53\u4E0E\u7EC6\u8282\u4E3A\u81EA\u62DF\uFF1B\u9AD8\u5EA6\u5927\u81F4\u4F9D\u4E66\u4E2D\u6570\u5B57\u3002"]),"godsway-monuments":a(["Godsway","\u795E\u8DEF"],["A broad grass road lined with statues, idols and stone kings carried off from conquered and dead cities.","\u5BBD\u9614\u7684\u8349\u5F84\uFF0C\u4E24\u65C1\u7ACB\u7740\u4ECE\u88AB\u5F81\u670D\u3001\u5DF2\u6E6E\u706D\u7684\u57CE\u5E02\u63A0\u6765\u7684\u96D5\u50CF\u3001\u795E\u50CF\u4E0E\u77F3\u96D5\u541B\u738B\u3002"],["Stolen gods and kings line the godsway: plunder from every land the Dothraki rode over.","\u795E\u8DEF\u4E24\u65C1\u5C3D\u662F\u63A0\u6765\u7684\u795E\u7947\u4E0E\u541B\u738B\uFF1A\u591A\u65AF\u62C9\u514B\u94C1\u8E44\u8E0F\u8FC7\u4E4B\u5730\u7684\u6218\u5229\u54C1\u3002"],"high",["agot","awoiaf"],["The road from the Horse Gate toward the Mother of Mountains is lined with plundered monuments from many lands.","\u81EA\u9A6C\u95E8\u901A\u5F80\u7FA4\u5C71\u4E4B\u6BCD\u7684\u5927\u9053\u4E24\u65C1\uFF0C\u9648\u5217\u7740\u63A0\u81EA\u8BF8\u591A\u571F\u5730\u7684\u53E4\u8FF9\u3002"],["Which monuments stand where, and in what order.","\u5404\u4EF6\u53E4\u8FF9\u7684\u5177\u4F53\u4F4D\u7F6E\u4E0E\u6392\u5217\u987A\u5E8F\u3002"],["Generic obelisks, statues, columns and cairns, evenly spaced.","\u4EE5\u901A\u7528\u7684\u65B9\u5C16\u7891\u3001\u96D5\u50CF\u3001\u77F3\u67F1\u4E0E\u77F3\u5806\u793A\u610F\uFF0C\u7B49\u8DDD\u6392\u5217\u3002"]),"western-market":a(["Western Market","\u897F\u5E02"],["A walled square of packed earth with stalls and shaded aisles, where merchants from the Free Cities and beyond trade.","\u4E00\u5904\u6709\u56F4\u5899\u7684\u592F\u571F\u65B9\u573A\uFF0C\u644A\u4F4D\u6797\u7ACB\u3001\u8FC7\u9053\u6709\u836B\uFF0C\u81EA\u7531\u8D38\u6613\u57CE\u90A6\u4E43\u81F3\u66F4\u8FDC\u5904\u7684\u5546\u4EBA\u5728\u6B64\u4EA4\u6613\u3002"],["Perfume, lace, wine and steel from the west are sold in the Western Market.","\u897F\u5E02\u552E\u5356\u6765\u81EA\u897F\u65B9\u7684\u9999\u6C34\u3001\u857E\u4E1D\u3001\u8461\u8404\u9152\u4E0E\u5200\u7532\u3002"],"high",["agot","awoiaf"],["A walled market of stalls where western goods are sold; merchants must honour the dosh khaleen with salt, silver and seed.","\u6709\u56F4\u5899\u7684\u5E02\u573A\uFF0C\u644A\u4F4D\u552E\u5356\u897F\u65B9\u8D27\u7269\uFF1B\u5546\u4EBA\u987B\u5411\u591A\u65AF\u5361\u6797\u732E\u4E0A\u76D0\u3001\u94F6\u4E0E\u79CD\u5B50\u3002"],["Its size and its exact place beside the godsway.","\u89C4\u6A21\uFF0C\u4EE5\u53CA\u5B83\u5728\u795E\u8DEF\u65C1\u7684\u786E\u5207\u4F4D\u7F6E\u3002"],["A low wall around awnings, tents and wagons; the size is invented.","\u77EE\u5899\u56F4\u7740\u906E\u9633\u68DA\u3001\u5E10\u7BF7\u4E0E\u8D27\u8F66\uFF1B\u89C4\u6A21\u4E3A\u81EA\u62DF\u3002"]),"eastern-market":a(["Eastern Market","\u4E1C\u5E02"],["The second market, where caravans from Yi Ti, Asshai and the Shadow Lands stop to trade.","\u7B2C\u4E8C\u5904\u5E02\u573A\uFF0C\u6765\u81EA\u5937\u5730\u3001\u4E9A\u590F\u4E0E\u9634\u5F71\u4E4B\u5730\u7684\u5546\u961F\u5728\u6B64\u505C\u9A7B\u4EA4\u6613\u3002"],["Caravans from the far east, with elephants and caged beasts, meet in the Eastern Market.","\u8FDC\u4E1C\u7684\u5546\u961F\u5E26\u7740\u5927\u8C61\u4E0E\u7B3C\u4E2D\u5F02\u517D\uFF0C\u5728\u4E1C\u5E02\u6C47\u805A\u3002"],"medium",["agot","awoiaf"],["A second market serves caravans from the east, including Yi Ti and Asshai.","\u53E6\u6709\u4E00\u5904\u5E02\u573A\u63A5\u5F85\u4E1C\u65B9\u5546\u961F\uFF0C\u5305\u62EC\u6765\u81EA\u5937\u5730\u4E0E\u4E9A\u590F\u8005\u3002"],["Its layout, size and position.","\u5E03\u5C40\u3001\u89C4\u6A21\u4E0E\u4F4D\u7F6E\u3002"],["The same open field as the Western Market, with different colours.","\u4E0E\u897F\u5E02\u76F8\u540C\u7684\u5F00\u9614\u573A\u5730\uFF0C\u53EA\u6362\u4E86\u914D\u8272\u3002"]),"khals-halls":a(["Halls of the Khals","\u53EF\u6C57\u6BBF\u5B87"],["Halls and houses raised by past khals, scattered through the grass and empty for much of the year.","\u5386\u4EE3\u53EF\u6C57\u4FEE\u5EFA\u7684\u6BBF\u5B87\u5C4B\u820D\uFF0C\u6563\u843D\u5728\u8349\u5730\u95F4\uFF0C\u4E00\u5E74\u4E2D\u5927\u534A\u7A7A\u7F6E\u3002"],["The city is built for every khalasar at once, so most of its halls stand empty.","\u8FD9\u5EA7\u57CE\u4E3A\u6240\u6709\u5361\u62C9\u8428\u540C\u65F6\u5230\u6765\u800C\u5EFA\uFF0C\u56E0\u6B64\u5927\u591A\u6570\u6BBF\u5B87\u7A7A\u7A7A\u8361\u8361\u3002"],"medium",["agot"],["Vaes Dothrak holds halls and palaces of many styles, built far larger than its usual population needs.","\u7EF4\u65AF\xB7\u591A\u65AF\u62C9\u514B\u6709\u5404\u5F0F\u6BBF\u5B87\u5BAB\u5BA4\uFF0C\u89C4\u6A21\u8FDC\u8D85\u5E73\u65E5\u7684\u4EBA\u53E3\u6240\u9700\u3002"],["Their form, number and layout.","\u5F62\u5236\u3001\u6570\u91CF\u4E0E\u5E03\u5C40\u3002"],["Eight long thatched halls placed at random.","\u516B\u5EA7\u8305\u9876\u957F\u6BBF\uFF0C\u968F\u610F\u5E03\u7F6E\u3002"]),"dosh-khaleen-huts":a(["Dosh Khaleen Huts","\u591A\u65AF\u5361\u6797\u5C45\u6240"],["A ring of round huts and a long hall standing for the home of the dosh khaleen, the widowed khaleesi who serve as seers.","\u4E00\u5708\u5706\u5C4B\u4E0E\u4E00\u5EA7\u957F\u5385\uFF0C\u4EE3\u8868\u591A\u65AF\u5361\u6797\u7684\u5C45\u6240\u3002\u5979\u4EEC\u662F\u4EA1\u6545\u53EF\u6C57\u7684\u9057\u5B40\uFF0C\u4E5F\u662F\u9884\u8A00\u8005\u3002"],["The dosh khaleen, widows of khals, speak prophecy; even the mightiest khal bows to them.","\u591A\u65AF\u5361\u6797\u662F\u4F17\u53EF\u6C57\u7684\u9057\u5B40\uFF0C\u5BA3\u793A\u9884\u8A00\uFF1B\u518D\u5F3A\u5927\u7684\u53EF\u6C57\u4E5F\u8981\u5411\u5979\u4EEC\u4F4E\u5934\u3002"],"medium",["agot","awoiaf"],["The dosh khaleen live in Vaes Dothrak, preside over its rites and are honoured by khals and traders alike.","\u591A\u65AF\u5361\u6797\u5C45\u4E8E\u7EF4\u65AF\xB7\u591A\u65AF\u62C9\u514B\uFF0C\u4E3B\u6301\u5723\u57CE\u7684\u4EEA\u5F0F\uFF0C\u53EF\u6C57\u4E0E\u5546\u4EBA\u90FD\u5BF9\u5979\u4EEC\u606D\u656C\u6709\u52A0\u3002"],["Where and how they live is not described here.","\u5979\u4EEC\u4F4F\u5728\u4F55\u5904\u3001\u5C45\u6240\u4F55\u6837\uFF0C\u6B64\u5904\u5E76\u65E0\u4F9D\u636E\u3002"],["The huts, the hall and their place near the mountain are invented.","\u5706\u5C4B\u3001\u957F\u5385\u53CA\u5176\u9760\u8FD1\u5723\u5C71\u7684\u4F4D\u7F6E\u5747\u4E3A\u81EA\u62DF\u3002"]),"womb-of-the-world":a(["Womb of the World","\u4E16\u754C\u4E4B\u5B50\u5BAB"],["A sacred lake; the Dothraki say the first man rose from its waters riding the first horse.","\u4E00\u5EA7\u5723\u6E56\uFF1B\u591A\u65AF\u62C9\u514B\u4EBA\u76F8\u4FE1\uFF0C\u7B2C\u4E00\u4E2A\u4EBA\u9A91\u7740\u7B2C\u4E00\u5339\u9A6C\u4ECE\u6E56\u4E2D\u5347\u8D77\u3002"],["The first rider rose from these waters, the Dothraki say. Rites end with a cleansing here.","\u591A\u65AF\u62C9\u514B\u4EBA\u8BF4\uFF0C\u7B2C\u4E00\u4F4D\u9A91\u624B\u4ECE\u8FD9\u7247\u6C34\u4E2D\u5347\u8D77\u3002\u4EEA\u5F0F\u8FC7\u540E\uFF0C\u4EBA\u4EEC\u6765\u6B64\u6C90\u6D74\u51C0\u8EAB\u3002"],"high",["agot","awoiaf"],["A holy lake near the Mother of Mountains, bound to the Dothraki origin myth and used for ritual bathing.","\u7FA4\u5C71\u4E4B\u6BCD\u9644\u8FD1\u7684\u5723\u6E56\uFF0C\u5173\u8054\u591A\u65AF\u62C9\u514B\u4EBA\u7684\u8D77\u6E90\u795E\u8BDD\uFF0C\u4E5F\u7528\u4E8E\u4EEA\u5F0F\u6C90\u6D74\u3002"],["Its real size, depth and shoreline.","\u771F\u5B9E\u5927\u5C0F\u3001\u6DF1\u5EA6\u4E0E\u5CB8\u7EBF\u3002"],["A round lake fringed with reeds near the mountain; reeds and shape are invented.","\u5C71\u811A\u9644\u8FD1\u4E00\u5EA7\u82A6\u82C7\u73AF\u7ED5\u7684\u5706\u6E56\uFF1B\u82A6\u82C7\u4E0E\u6E56\u5F62\u4E3A\u81EA\u62DF\u3002"]),"mother-of-mountains":a(["Mother of Mountains","\u7FA4\u5C71\u4E4B\u6BCD"],["The holy mountain that rises over the city, at the far end of the godsway; only men may set foot on it.","\u8038\u7ACB\u4E8E\u57CE\u5E02\u4E0A\u65B9\u7684\u5723\u5C71\uFF0C\u5728\u795E\u8DEF\u5C3D\u5934\uFF1B\u53EA\u8BB8\u7537\u5B50\u8E0F\u8DB3\u3002"],["The Mother of Mountains rises over the city. Only men may climb her slopes.","\u7FA4\u5C71\u4E4B\u6BCD\u4FEF\u4E34\u5168\u57CE\uFF0C\u53EA\u6709\u7537\u5B50\u53EF\u4EE5\u767B\u4E0A\u5979\u7684\u5C71\u5761\u3002"],"high",["agot","awoiaf"],["A holy mountain beside the city, which only men may set foot on.","\u57CE\u65C1\u7684\u5723\u5C71\uFF0C\u53EA\u8BB8\u7537\u5B50\u8E0F\u8DB3\u3002"],["Its actual height and shape.","\u5B9E\u9645\u9AD8\u5EA6\u4E0E\u5F62\u72B6\u3002"],["A broad rounded massif with a gentle outline, scaled to fit the scene.","\u8F6E\u5ED3\u67D4\u548C\u7684\u5BBD\u9614\u6D51\u5706\u5C71\u4F53\uFF0C\u6309\u573A\u666F\u9700\u8981\u7F29\u653E\u3002"]),"sea-of-grass":a(["Dothraki Sea","\u591A\u65AF\u62C9\u514B\u6D77"],["Grass rolling to every horizon, with grazing herds and riders.","\u8349\u6D6A\u8D77\u4F0F\uFF0C\u76F4\u62B5\u5929\u8FB9\uFF0C\u9A6C\u7FA4\u5403\u8349\uFF0C\u9A91\u624B\u9A70\u8FC7\u3002"],["Around the city there is only grass and sky, as far as a horse can run.","\u57CE\u5916\u53EA\u6709\u9752\u8349\u4E0E\u957F\u5929\uFF0C\u9A6C\u80FD\u8DD1\u591A\u8FDC\uFF0C\u4FBF\u5EF6\u4F38\u591A\u8FDC\u3002"],"high",["agot"],["Vaes Dothrak stands in the Dothraki sea, an immense grassland.","\u7EF4\u65AF\xB7\u591A\u65AF\u62C9\u514B\u4F4D\u4E8E\u591A\u65AF\u62C9\u514B\u6D77\uFF0C\u4E00\u7247\u65E0\u57A0\u7684\u8349\u539F\u3002"],["The local landscape in detail.","\u5F53\u5730\u5730\u8C8C\u7EC6\u8282\u3002"],["Gently rolling ground with tufts of grass and herds.","\u548C\u7F13\u8D77\u4F0F\u7684\u5730\u9762\uFF0C\u70B9\u7F00\u8349\u4E1B\u4E0E\u9A6C\u7FA4\u3002"])}};export{m as default};
